1	//! Structured wasm control flow lowered to LLVM blocks and fixed operand slots.
2	use crate::numeric;
3	use crate::wasm::ValType::{self, I32, I64, F32, F64, V128, FuncRef, ExternRef};
4	use std::collections::BTreeSet;
5	use std::fmt::Write;
6	
7	#[derive(Clone, Debug, PartialEq, Eq)]
8	pub struct Sig { pub params: Vec<ValType>, pub results: Vec<ValType> }
9	#[derive(Clone)]
10	pub struct Env {
11	    pub types: Vec<Sig>, pub funcs: Vec<u32>, pub globals: Vec<(ValType,bool)>,
12	    pub memory: bool, pub tables: Vec<ValType>, pub data_count: usize, pub elem_types: Vec<ValType>,
13	}
14	pub struct FunctionIR { pub body: String, pub numeric: BTreeSet<u32> }
15	
16	pub struct Reader<'a> { bytes: &'a [u8], pos: usize }
17	impl<'a> Reader<'a> {
18	    fn new(bytes: &'a [u8]) -> Self { Self { bytes, pos: 0 } }
19	    fn byte(&mut self) -> Result<u8,String> { let b=*self.bytes.get(self.pos).ok_or("unexpected end of function")?; self.pos+=1; Ok(b) }
20	    fn bytes(&mut self, n:usize) -> Result<&'a [u8],String> { let end=self.pos.checked_add(n).ok_or("length overflow")?; let b=self.bytes.get(self.pos..end).ok_or("truncated immediate")?; self.pos=end; Ok(b) }
21	    fn u32(&mut self) -> Result<u32,String> {
22	        let mut n=0u64;
23	        for i in 0..5 { let b=self.byte()?; n|=((b&127) as u64)<<(7*i); if b&128==0 { return u32::try_from(n).map_err(|_|"integer too large".into()); } }
24	        Err("integer representation too long".into())
25	    }
26	    fn signed(&mut self, bits:u32) -> Result<i64,String> {
27	        let mut n=0i128; let mut shift=0u32;
28	        for _ in 0..((bits+6)/7) { let b=self.byte()?; n|=((b&127) as i128)<<shift; shift+=7; if b&128==0 { if b&64!=0 { n |= (!0i128)<<shift; } let min=-(1i128<<(bits-1)); let max=(1i128<<(bits-1))-1; if n<min||n>max {return Err("signed integer too large".into())} return Ok(n as i64); } }
29	        Err("signed integer representation too long".into())
30	    }
31	    fn done(&self)->bool {self.pos==self.bytes.len()}
32	}
33	fn value_type(b:u8)->Result<ValType,String> { match b {0x7f=>Ok(I32),0x7e=>Ok(I64),0x7d=>Ok(F32),0x7c=>Ok(F64),0x7b=>Ok(V128),0x70=>Ok(FuncRef),0x6f=>Ok(ExternRef),_=>Err(format!("invalid value type {b:#x}"))} }
34	
35	#[derive(Clone, Copy, PartialEq, Eq)]
36	enum Kind { Function, Block, Loop, If }
37	#[derive(Clone)]
38	struct Frame { kind:Kind, base:usize, params:Vec<ValType>, results:Vec<ValType>, target:String, end:String, otherwise:String, has_else:bool, unreachable:bool }
39	impl Frame { fn branch_types(&self)->&[ValType] { if self.kind==Kind::Loop { &self.params } else { &self.results } } }
40	
41	struct Compiler<'a> {
42	    env:&'a Env, r:Reader<'a>, out:String, stack:Vec<Option<ValType>>, frames:Vec<Frame>,
43	    locals:Vec<ValType>, max_stack:usize, max_args:usize, max_results:usize,
44	    next_id:usize, numeric:BTreeSet<u32>,
45	}
46	impl<'a> Compiler<'a> {
47	    fn line(&mut self, line:impl AsRef<str>) { writeln!(self.out,"  {}",line.as_ref()).unwrap(); }
48	    fn fresh(&mut self)->String { let n=self.next_id; self.next_id+=1; format!("%v{n}") }
49	    fn label(&mut self)->String { let n=self.next_id; self.next_id+=1; format!("b{n}") }
50	    fn put_label(&mut self,l:&str) { writeln!(self.out,"{l}:").unwrap(); }
51	    fn top(&self)->&Frame { self.frames.last().expect("frame") }
52	    fn touch(&mut self, i:usize) {self.max_stack=self.max_stack.max(i+1);}
53	    fn pop(&mut self, want:Option<ValType>)->Result<usize,String> {
54	        let f=self.top(); let (base,unreachable)=(f.base,f.unreachable);
55	        if self.stack.len()==base {
56	            if unreachable { self.touch(base); return Ok(base); }
57	            return Err("operand stack underflow".into());
58	        }
59	        let i=self.stack.len()-1; let actual=self.stack.pop().unwrap();
60	        if let (Some(x),Some(y))=(actual,want) { if x!=y { return Err(format!("operand type mismatch: {x:?} vs {y:?}")); } }
61	        Ok(i)
62	    }
63	    fn push(&mut self,t:Option<ValType>)->usize {let i=self.stack.len(); self.stack.push(t); self.touch(i); i}
64	    fn load(&mut self, i:usize)->String {self.touch(i); let v=self.fresh(); self.line(format!("{v} = load i128, ptr %s{i}, align 16")); v}
65	    fn store(&mut self,i:usize,v:&str) {self.touch(i); self.line(format!("store i128 {v}, ptr %s{i}, align 16"));}
66	    fn push_val(&mut self,t:ValType,v:&str) {let i=self.push(Some(t));self.store(i,v);}
67	    fn get_pop(&mut self,t:ValType)->Result<String,String> {let i=self.pop(Some(t))?; Ok(self.load(i))}
68	    fn i32(&mut self,v:&str)->String {let x=self.fresh();self.line(format!("{x} = trunc i128 {v} to i32"));x}
69	    fn widen(&mut self,v:&str,ty:&str)->String {let x=self.fresh();self.line(format!("{x} = zext {ty} {v} to i128"));x}
70	    fn dead(&mut self) {let f=self.frames.last_mut().unwrap(); self.stack.truncate(f.base);f.unreachable=true;let lab=self.label();self.put_label(&lab);}
71	    fn check_args(&mut self, types:&[ValType])->Result<Vec<usize>,String> {
72	        let mut v=Vec::new(); for &t in types.iter().rev() { v.push(self.pop(Some(t))?); } v.reverse(); Ok(v)
73	    }
74	    fn check_branch(&mut self, frame:&Frame)->Result<Vec<usize>,String> {
75	        let orig=self.stack.clone(); let args=self.check_args(frame.branch_types())?; self.stack=orig; Ok(args)
76	    }
77	    fn move_values(&mut self, from:&[usize], base:usize) {
78	        let values:Vec<_>=from.iter().map(|&i|self.load(i)).collect();
79	        for (i,v) in values.iter().enumerate() { self.store(base+i,v); }
80	    }
81	    fn finish_arm(&mut self, frame:&Frame)->Result<(),String> {
82	        let values=self.check_args(&frame.results)?;
83	        if self.stack.len()!=frame.base { return Err("values left on stack at end of block".into()); }
84	        self.move_values(&values,frame.base);
85	        self.line(format!("br label %{}",frame.end));
86	        Ok(())
87	    }
88	    fn block_sig(&mut self)->Result<Sig,String> {
89	        let b=self.r.byte()?;
90	        if b==0x40 {return Ok(Sig{params:vec![],results:vec![]})}
91	        if let Ok(t)=value_type(b) {return Ok(Sig{params:vec![],results:vec![t]})}
92	        self.r.pos-=1; let i=self.r.signed(33)?; if i<0 {return Err("invalid block type".into())}
93	        self.env.types.get(i as usize).cloned().ok_or("block type index out of bounds".into())
94	    }
95	    fn start_control(&mut self,kind:Kind)->Result<(),String> {
96	        let sig=self.block_sig()?;
97	        let cond=if kind==Kind::If { let v=self.get_pop(I32)?;Some(self.i32(&v)) } else {None};
98	        let vals=self.check_args(&sig.params)?;
99	        let base=self.stack.len();
100	        let loaded:Vec<_>=vals.iter().map(|&i|self.load(i)).collect();
101	        for (&t,v) in sig.params.iter().zip(loaded.iter()) {self.push_val(t,v);}
102	        let end=self.label(); let otherwise=if kind==Kind::If {self.label()} else {String::new()};
103	        let target=if kind==Kind::Loop {let l=self.label();self.line(format!("br label %{l}"));self.put_label(&l);l} else {end.clone()};
104	        if let Some(cond)=cond {let yes=self.label();let test=self.fresh();self.line(format!("{test} = icmp ne i32 {cond}, 0"));self.line(format!("br i1 {test}, label %{yes}, label %{otherwise}"));self.put_label(&yes);}
105	        self.frames.push(Frame{kind,base,params:sig.params,results:sig.results,target,end,otherwise,has_else:false,unreachable:false});
106	        Ok(())
107	    }
108	    fn else_arm(&mut self)->Result<(),String> {
109	        let frame=self.top().clone();
110	        if frame.kind!=Kind::If || frame.has_else {return Err("unexpected else".into())}
111	        self.finish_arm(&frame)?;
112	        self.put_label(&frame.otherwise);
113	        self.stack.truncate(frame.base);
114	        for t in &frame.params { self.push(Some(*t)); }
115	        let f=self.frames.last_mut().unwrap(); f.has_else=true;f.unreachable=false;
116	        Ok(())
117	    }
118	    /// Returns true for the function's closing end.
119	    fn end(&mut self)->Result<bool,String> {
120	        let f=self.top().clone();
121	        self.finish_arm(&f)?;
122	        if f.kind==Kind::If && !f.has_else {
123	            if f.params!=f.results {return Err("if without else has incompatible result".into())}
124	            self.put_label(&f.otherwise); self.line(format!("br label %{}",f.end));
125	        }
126	        self.frames.pop();
127	        if f.kind==Kind::Function {return Ok(true)}
128	        self.put_label(&f.end); self.stack.truncate(f.base); for t in f.results {self.push(Some(t));}
129	        Ok(false)
130	    }
131	    fn frame_at(&self,depth:u32)->Result<Frame,String> {let i=self.frames.len().checked_sub(depth as usize+1).ok_or("invalid branch depth")?; Ok(self.frames[i].clone())}
132	    fn do_branch(&mut self,depth:u32, conditional:bool)->Result<(),String> {
133	        let cond=if conditional {let v=self.get_pop(I32)?;Some(self.i32(&v))} else {None};
134	        let f=self.frame_at(depth)?; let args=self.check_branch(&f)?;
135	        if let Some(cond)=cond {
136	            let taken=self.label();let next=self.label();let c=self.fresh();
137	            self.line(format!("{c} = icmp ne i32 {cond}, 0"));self.line(format!("br i1 {c}, label %{taken}, label %{next}"));
138	            self.put_label(&taken);self.move_values(&args,f.base);self.line(format!("br label %{}",f.target));self.put_label(&next);
139	        } else {self.move_values(&args,f.base);self.line(format!("br label %{}",f.target));self.dead();}
140	        Ok(())
141	    }
142	    fn br_table(&mut self)->Result<(),String> {
143	        let n=self.r.u32()? as usize;if n>self.r.bytes.len(){return Err("br_table too long".into())}
144	        let mut depths=Vec::with_capacity(n+1);for _ in 0..=n {depths.push(self.r.u32()?);}
145	        let sel=self.get_pop(I32)?;let sel=self.i32(&sel);
146	        let frames:Vec<_>=depths.iter().map(|&d|self.frame_at(d)).collect::<Result<_,_>>()?;
147	        let ty=frames.last().unwrap().branch_types().to_vec();
148	        for f in &frames {if f.branch_types()!=ty {return Err("br_table label types differ".into())}}
149	        let args=self.check_branch(frames.last().unwrap())?;
150	        let labs:Vec<_>=(0..=n).map(|_|self.label()).collect();
151	        self.line(format!("switch i32 {sel}, label %{} [",labs[n]));
152	        for i in 0..n {self.line(format!("  i32 {i}, label %{}",labs[i]));}self.line("]");
153	        for (f,l) in frames.iter().zip(&labs) {self.put_label(l);self.move_values(&args,f.base);self.line(format!("br label %{}",f.target));}
154	        self.dead();Ok(())
155	    }
156	    fn local_get(&mut self,i:u32)->Result<(),String> {let t=*self.locals.get(i as usize).ok_or("invalid local index")?;let v=self.fresh();self.line(format!("{v} = load i128, ptr %l{i}, align 16"));self.push_val(t,&v);Ok(())}
157	    fn local_set(&mut self,i:u32,tee:bool)->Result<(),String> {let t=*self.locals.get(i as usize).ok_or("invalid local index")?;let idx=self.pop(Some(t))?;let v=self.load(idx);self.line(format!("store i128 {v}, ptr %l{i}, align 16"));if tee {self.push_val(t,&v)}Ok(())}
158	    fn global(&mut self,i:u32,set:bool)->Result<(),String> {let (t,mutable)=*self.env.globals.get(i as usize).ok_or("invalid global index")?;if set {if !mutable{return Err("immutable global set".into())}let v=self.get_pop(t)?;self.line(format!("store i128 {v}, ptr @w2l_g{i}, align 16"));}else {let v=self.fresh();self.line(format!("{v} = load i128, ptr @w2l_g{i}, align 16"));self.push_val(t,&v);}Ok(())}
159	    fn call(&mut self,index:u32, indirect:Option<u32>)->Result<(),String> {
160	        let tid=if indirect.is_some(){index}else{*self.env.funcs.get(index as usize).ok_or("invalid function index")?};
161	        let sig=self.env.types.get(tid as usize).ok_or("invalid function type")?.clone();
162	        let table_index=if let Some(tab)=indirect {if self.env.tables.get(tab as usize)!=Some(&FuncRef){return Err("invalid indirect-call table".into())}let i=self.get_pop(I32)?;Some(self.i32(&i))}else{None};
163	        let args=self.check_args(&sig.params)?;self.max_args=self.max_args.max(sig.params.len());self.max_results=self.max_results.max(sig.results.len());
164	        for (j,i) in args.iter().enumerate() {let v=self.load(*i);let p=self.fresh();self.line(format!("{p} = getelementptr i128, ptr %callargs, i64 {j}"));self.line(format!("store i128 {v}, ptr {p}, align 16"));}
165	        if let Some(x)=table_index {self.line(format!("call void @w2l_indirect_{tid}_{0}(i32 {x}, ptr %callargs, ptr %callresults)",indirect.unwrap()));}
166	        else {self.line(format!("call void @w2l_f{index}(ptr %callargs, ptr %callresults)"));}
167	        for (j,t) in sig.results.iter().enumerate() {let p=self.fresh();self.line(format!("{p} = getelementptr i128, ptr %callresults, i64 {j}"));let v=self.fresh();self.line(format!("{v} = load i128, ptr {p}, align 16"));self.push_val(*t,&v);}
168	        Ok(())
169	    }
170	    fn numeric(&mut self,op:u32)->Result<(),String> {
171	        let (types,ret)=numeric::signature(op).ok_or_else(||format!("unsupported numeric opcode {op:x}"))?;
172	        let args=self.check_args(&types)?;let a=self.load(args[0]);let b=if args.len()>1 {self.load(args[1])} else {"0".into()};let v=self.fresh();
173	        self.line(format!("{v} = call i128 @w2l_num_{op:x}(i128 {a}, i128 {b})"));self.push_val(ret,&v);self.numeric.insert(op);Ok(())
174	    }
175	    fn memop(&mut self,op:u8)->Result<(),String> {
176	        if !self.env.memory {return Err("memory instruction without memory".into())}
177	        let (t,width,store,signed):(ValType,u32,bool,bool)=match op {
178	            0x28=>(I32,4,false,false),0x29=>(I64,8,false,false),0x2a=>(F32,4,false,false),0x2b=>(F64,8,false,false),
179	            0x2c=>(I32,1,false,true),0x2d=>(I32,1,false,false),0x2e=>(I32,2,false,true),0x2f=>(I32,2,false,false),
180	            0x30=>(I64,1,false,true),0x31=>(I64,1,false,false),0x32=>(I64,2,false,true),0x33=>(I64,2,false,false),0x34=>(I64,4,false,true),0x35=>(I64,4,false,false),
181	            0x36=>(I32,4,true,false),0x37=>(I64,8,true,false),0x38=>(F32,4,true,false),0x39=>(F64,8,true,false),
182	            0x3a=>(I32,1,true,false),0x3b=>(I32,2,true,false),0x3c=>(I64,1,true,false),0x3d=>(I64,2,true,false),0x3e=>(I64,4,true,false),_=>unreachable!()};
183	        let align=self.r.u32()?;let offset=self.r.u32()?;if align>width.trailing_zeros(){return Err("invalid memory alignment".into())}
184	        let value=if store {Some(self.get_pop(t)?)} else {None};let addr=self.get_pop(I32)?;let addr=self.i32(&addr);
185	        let ptr=self.fresh();self.line(format!("{ptr} = call ptr @w2l_mem_ptr(i32 {addr}, i64 {offset}, i64 {width})"));let wt=format!("i{}",width*8);
186	        if let Some(value)=value {let v=self.fresh();self.line(format!("{v} = trunc i128 {value} to {wt}"));self.line(format!("store {wt} {v}, ptr {ptr}, align 1"));}
187	        else {let v=self.fresh();self.line(format!("{v} = load {wt}, ptr {ptr}, align 1"));let out=if signed {let to=if t==I32 {"i32"}else{"i64"};let ext=self.fresh();self.line(format!("{ext} = sext {wt} {v} to {to}"));self.widen(&ext,to)} else {self.widen(&v,&wt)};self.push_val(t,&out);}
188	        Ok(())
189	    }
190	    fn bulk(&mut self)->Result<(),String> {
191	        let op=self.r.u32()?;
192	        if op<=7 {return self.numeric(0x100+op)}
193	        match op {
194	            8=>{let data=self.r.u32()?;let mem=self.r.u32()?;if !self.env.memory||mem!=0||data as usize>=self.env.data_count{return Err("invalid memory.init index".into())}let n=self.get_pop(I32)?;let src=self.get_pop(I32)?;let dst=self.get_pop(I32)?;let n=self.i32(&n);let src=self.i32(&src);let dst=self.i32(&dst);self.line(format!("call void @w2l_data_init_{data}(i32 {dst}, i32 {src}, i32 {n})"));}
195	            9=>{let data=self.r.u32()?;if data as usize>=self.env.data_count{return Err("invalid data.drop index".into())}self.line(format!("store i1 true, ptr @w2l_data_dropped_{data}"));}
196	            10=>{let a=self.r.u32()?;let b=self.r.u32()?;if !self.env.memory||a!=0||b!=0{return Err("invalid memory.copy index".into())}let n=self.get_pop(I32)?;let src=self.get_pop(I32)?;let dst=self.get_pop(I32)?;let n=self.i32(&n);let src=self.i32(&src);let dst=self.i32(&dst);self.line(format!("call void @w2l_mem_copy(i32 {dst}, i32 {src}, i32 {n})"));}
197	            11=>{let mem=self.r.u32()?;if !self.env.memory||mem!=0{return Err("invalid memory.fill index".into())}let n=self.get_pop(I32)?;let byte=self.get_pop(I32)?;let dst=self.get_pop(I32)?;let n=self.i32(&n);let byte=self.i32(&byte);let dst=self.i32(&dst);self.line(format!("call void @w2l_mem_fill(i32 {dst}, i32 {byte}, i32 {n})"));}
198	            12=>{let e=self.r.u32()?;let t=self.r.u32()?;let et=self.env.elem_types.get(e as usize).ok_or("invalid element index")?;if self.env.tables.get(t as usize)!=Some(et){return Err("table.init type mismatch".into())}let n=self.get_pop(I32)?;let src=self.get_pop(I32)?;let dst=self.get_pop(I32)?;let n=self.i32(&n);let src=self.i32(&src);let dst=self.i32(&dst);let p=self.fresh();let q=self.fresh();let size=self.fresh();self.line(format!("{p} = call ptr @w2l_table_ptr_{t}(i32 {dst}, i32 {n})"));self.line(format!("{q} = call ptr @w2l_elem_ptr_{e}(i32 {src}, i32 {n})"));self.line(format!("{size} = zext i32 {n} to i64"));let bytes=self.fresh();self.line(format!("{bytes} = shl i64 {size}, 4"));self.line(format!("call void @llvm.memcpy.p0.p0.i64(ptr {p}, ptr {q}, i64 {bytes}, i1 false)"));}
199	            13=>{let e=self.r.u32()?;if e as usize>=self.env.elem_types.len(){return Err("invalid elem.drop index".into())}self.line(format!("store i1 true, ptr @w2l_elem_dropped_{e}"));}
200	            14=>{let a=self.r.u32()?;let b=self.r.u32()?;let ta=self.env.tables.get(a as usize).ok_or("invalid table index")?;if self.env.tables.get(b as usize)!=Some(ta){return Err("table.copy type mismatch".into())}let n=self.get_pop(I32)?;let src=self.get_pop(I32)?;let dst=self.get_pop(I32)?;let n=self.i32(&n);let src=self.i32(&src);let dst=self.i32(&dst);let p=self.fresh();let q=self.fresh();let size=self.fresh();let bytes=self.fresh();self.line(format!("{p} = call ptr @w2l_table_ptr_{a}(i32 {dst}, i32 {n})"));self.line(format!("{q} = call ptr @w2l_table_ptr_{b}(i32 {src}, i32 {n})"));self.line(format!("{size} = zext i32 {n} to i64"));self.line(format!("{bytes} = shl i64 {size}, 4"));self.line(format!("call void @llvm.memmove.p0.p0.i64(ptr {p}, ptr {q}, i64 {bytes}, i1 false)"));}
201	            15=>{let t=self.r.u32()?;let ty=*self.env.tables.get(t as usize).ok_or("invalid table index")?;let delta=self.get_pop(I32)?;let delta=self.i32(&delta);let val=self.get_pop(ty)?;let r=self.fresh();self.line(format!("{r} = call i32 @w2l_table_grow_{t}(i128 {val}, i32 {delta})"));let w=self.widen(&r,"i32");self.push_val(I32,&w);}
202	            16=>{let t=self.r.u32()?;if self.env.tables.get(t as usize).is_none(){return Err("invalid table index".into())}let s=self.fresh();let n=self.fresh();let w=self.fresh();self.line(format!("{s} = load i64, ptr @w2l_table_size_{t}"));self.line(format!("{n} = trunc i64 {s} to i32"));self.line(format!("{w} = zext i32 {n} to i128"));self.push_val(I32,&w);}
203	            17=>{let t=self.r.u32()?;let ty=*self.env.tables.get(t as usize).ok_or("invalid table index")?;let n=self.get_pop(I32)?;let n=self.i32(&n);let val=self.get_pop(ty)?;let start=self.get_pop(I32)?;let start=self.i32(&start);self.line(format!("call void @w2l_table_fill_{t}(i32 {start}, i128 {val}, i32 {n})"));}
204	            _=>return Err(format!("unsupported 0xfc instruction {op}")),
205	        }Ok(())
206	    }
207	    fn instruction(&mut self,op:u8)->Result<bool,String> {
208	        match op {
209	            0x00=>{self.line("call void @w2l_trap(i32 0)");self.line("unreachable");self.dead();}
210	            0x01=>{},0x02=>self.start_control(Kind::Block)?,0x03=>self.start_control(Kind::Loop)?,0x04=>self.start_control(Kind::If)?,0x05=>self.else_arm()?,0x0b=>return self.end(),
211	            0x0c=>{let i=self.r.u32()?;self.do_branch(i,false)?},0x0d=>{let i=self.r.u32()?;self.do_branch(i,true)?},0x0e=>self.br_table()?,
212	            0x0f=>{let i=(self.frames.len()-1) as u32;self.do_branch(i,false)?},
213	            0x10=>{let i=self.r.u32()?;self.call(i,None)?},0x11=>{let i=self.r.u32()?;let t=self.r.u32()?;self.call(i,Some(t))?},
214	            0x1a=>{self.pop(None)?;},
215	            0x1b|0x1c=>{
