217	                let c=self.get_pop(I32)?;let c=self.i32(&c);let yt=if self.stack.len()>self.top().base { self.stack.last().copied().flatten() } else { None };let yidx=self.pop(ty)?;
218	                // If the second operand was popped from a polymorphic stack its type is unknown.
219	                let expected=ty.or(yt);let xidx=self.pop(expected)?;let x=self.load(xidx);let y=self.load(yidx);
220	                let typ=expected.unwrap_or(I32);if op==0x1b&&matches!(typ,FuncRef|ExternRef){return Err("untyped select on reference".into())}
221	                let p=self.fresh();let v=self.fresh();self.line(format!("{p} = icmp ne i32 {c}, 0"));self.line(format!("{v} = select i1 {p}, i128 {x}, i128 {y}"));self.push_val(typ,&v);
222	            }
223	            0x20=>{let i=self.r.u32()?;self.local_get(i)?},0x21=>{let i=self.r.u32()?;self.local_set(i,false)?},0x22=>{let i=self.r.u32()?;self.local_set(i,true)?},0x23=>{let i=self.r.u32()?;self.global(i,false)?},0x24=>{let i=self.r.u32()?;self.global(i,true)?},
224	            0x25=>{let t=self.r.u32()?;let ty=*self.env.tables.get(t as usize).ok_or("invalid table index")?;let index=self.get_pop(I32)?;let index=self.i32(&index);let v=self.fresh();self.line(format!("{v} = call i128 @w2l_table_get_{t}(i32 {index})"));self.push_val(ty,&v);}
225	            0x26=>{let t=self.r.u32()?;let ty=*self.env.tables.get(t as usize).ok_or("invalid table index")?;let val=self.get_pop(ty)?;let index=self.get_pop(I32)?;let index=self.i32(&index);self.line(format!("call void @w2l_table_set_{t}(i32 {index}, i128 {val})"));}
