228	            0x40=>{let mem=self.r.u32()?;if mem!=0||!self.env.memory{return Err("invalid memory.grow".into())}let d=self.get_pop(I32)?;let d=self.i32(&d);let r=self.fresh();self.line(format!("{r} = call i32 @w2l_mem_grow(i32 {d})"));let r=self.widen(&r,"i32");self.push_val(I32,&r);}
229	            0x41=>{let x=self.r.signed(32)? as u32;self.push_val(I32,&x.to_string());},0x42=>{let x=self.r.signed(64)? as u64;self.push_val(I64,&x.to_string());},
230	            0x43=>{let b=self.r.bytes(4)?;let x=u32::from_le_bytes(b.try_into().unwrap());self.push_val(F32,&x.to_string());},0x44=>{let b=self.r.bytes(8)?;let x=u64::from_le_bytes(b.try_into().unwrap());self.push_val(F64,&x.to_string());},
231	            0x45..=0xc4=>self.numeric(op as u32)?,
232	            0xd0=>{let ty=value_type(self.r.byte()?)?;if !matches!(ty,FuncRef|ExternRef){return Err("invalid ref.null type".into())}self.push_val(ty,"0");}
233	            0xd1=>{let ty=if self.stack.len()>self.top().base{self.stack.last().copied().flatten()}else{None};if let Some(t)=ty {if !matches!(t,FuncRef|ExternRef){return Err("ref.is_null expects a reference".into())}}let i=self.pop(None)?;let v=self.load(i);let p=self.fresh();let r=self.fresh();self.line(format!("{p} = icmp eq i128 {v}, 0"));self.line(format!("{r} = zext i1 {p} to i128"));self.push_val(I32,&r);}
