235	            0xfc=>self.bulk()?,
236	            _=>return Err(format!("unsupported opcode 0x{op:02x}")),
237	        }Ok(false)
238	    }
239	}
240	
241	pub fn compile(index:u32, env:&Env, sig:&Sig, locals:&[ValType], code:&[u8])->Result<FunctionIR,String> {
242	    let all_locals=sig.params.iter().chain(locals).copied().collect();
243	    let frame=Frame{kind:Kind::Function,base:0,params:vec![],results:sig.results.clone(),target:"return".into(),end:"return".into(),otherwise:String::new(),has_else:false,unreachable:false};
244	    let mut c=Compiler{env,r:Reader::new(code),out:String::new(),stack:vec![],frames:vec![frame],locals:all_locals,max_stack:0,max_args:0,max_results:0,next_id:0,numeric:BTreeSet::new()};
245	    loop {let op=c.r.byte()?;if c.instruction(op)? {break}}
246	    if !c.r.done() {return Err("bytes after function end".into())}
247	    c.put_label("return");
248	    for i in 0..sig.results.len() {let v=c.load(i);let p=c.fresh();c.line(format!("{p} = getelementptr i128, ptr %results, i64 {i}"));c.line(format!("store i128 {v}, ptr {p}, align 1"));}
249	    c.line("%depth_after = load i32, ptr @w2l_depth");c.line("%depth_less = sub i32 %depth_after, 1");c.line("store i32 %depth_less, ptr @w2l_depth");c.line("ret void");
250	    let mut s=format!("define internal void @w2l_f{index}(ptr %args, ptr %results) {{\nentry:\n");
251	    writeln!(s,"  %depth_before = load i32, ptr @w2l_depth\n  %depth_next = add i32 %depth_before, 1\n  store i32 %depth_next, ptr @w2l_depth\n  %depth_exceeded = icmp ugt i32 %depth_next, 50000\n  br i1 %depth_exceeded, label %exhausted, label %body\nexhausted:\n  call void @w2l_trap(i32 8)\n  unreachable\nbody:").unwrap();
252	    for i in 0..c.max_stack {writeln!(s,"  %s{i} = alloca i128, align 16").unwrap();}
253	    for i in 0..c.locals.len() {writeln!(s,"  %l{i} = alloca i128, align 16").unwrap();}
254	    writeln!(s,"  %callargs = alloca [{} x i128], align 16\n  %callresults = alloca [{} x i128], align 16",c.max_args.max(1),c.max_results.max(1)).unwrap();
255	    for i in 0..c.locals.len() { if i<sig.params.len() {writeln!(s,"  %p{i} = getelementptr i128, ptr %args, i64 {i}\n  %arg{i} = load i128, ptr %p{i}, align 1\n  store i128 %arg{i}, ptr %l{i}, align 16").unwrap();} else {writeln!(s,"  store i128 0, ptr %l{i}, align 16").unwrap();} }
256	    s.push_str(&c.out);s.push_str("}\n\n");
257	    Ok(FunctionIR{body:s,numeric:c.numeric})
258	}
