1	//! Structured wasm control flow lowered to LLVM blocks and fixed operand slots.
2	use crate::numeric;
3	use crate::wasm::ValType::{self, I32, I64, F32, F64, V128, FuncRef, ExternRef};
4	use std::collections::BTreeSet;
5	use std::fmt::Write;
6	
7	#[derive(Clone, Debug, PartialEq, Eq)]
8	pub struct Sig { pub params: Vec<ValType>, pub results: Vec<ValType> }
9	#[derive(Clone)]
10	pub struct Env {
11	    pub types: Vec<Sig>, pub funcs: Vec<u32>, pub globals: Vec<(ValType,bool)>,
12	    pub memory: bool, pub tables: Vec<ValType>, pub data_count: usize, pub elem_types: Vec<ValType>,
13	}
14	pub struct FunctionIR { pub body: String, pub numeric: BTreeSet<u32> }
15	
16	pub struct Reader<'a> { bytes: &'a [u8], pos: usize }
17	impl<'a> Reader<'a> {
18	    fn new(bytes: &'a [u8]) -> Self { Self { bytes, pos: 0 } }
19	    fn byte(&mut self) -> Result<u8,String> { let b=*self.bytes.get(self.pos).ok_or("unexpected end of function")?; self.pos+=1; Ok(b) }
20	    fn bytes(&mut self, n:usize) -> Result<&'a [u8],String> { let end=self.pos.checked_add(n).ok_or("length overflow")?; let b=self.bytes.get(self.pos..end).ok_or("truncated immediate")?; self.pos=end; Ok(b) }
21	    fn u32(&mut self) -> Result<u32,String> {
22	        let mut n=0u64;
23	        for i in 0..5 { let b=self.byte()?; n|=((b&127) as u64)<<(7*i); if b&128==0 { return u32::try_from(n).map_err(|_|"integer too large".into()); } }
24	        Err("integer representation too long".into())
25	    }
26	    fn signed(&mut self, bits:u32) -> Result<i64,String> {
27	        let mut n=0i128; let mut shift=0u32;
28	        for _ in 0..((bits+6)/7) { let b=self.byte()?; n|=((b&127) as i128)<<shift; shift+=7; if b&128==0 { if b&64!=0 { n |= (!0i128)<<shift; } let min=-(1i128<<(bits-1)); let max=(1i128<<(bits-1))-1; if n<min||n>max {return Err("signed integer too large".into())} return Ok(n as i64); } }
29	        Err("signed integer representation too long".into())
30	    }
31	    fn done(&self)->bool {self.pos==self.bytes.len()}
32	}
33	fn value_type(b:u8)->Result<ValType,String> { match b {0x7f=>Ok(I32),0x7e=>Ok(I64),0x7d=>Ok(F32),0x7c=>Ok(F64),0x7b=>Ok(V128),0x70=>Ok(FuncRef),0x6f=>Ok(ExternRef),_=>Err(format!("invalid value type {b:#x}"))} }
34	
35	#[derive(Clone, Copy, PartialEq, Eq)]
36	enum Kind { Function, Block, Loop, If }
37	#[derive(Clone)]
38	struct Frame { kind:Kind, base:usize, params:Vec<ValType>, results:Vec<ValType>, target:String, end:String, otherwise:String, has_else:bool, unreachable:bool }
39	impl Frame { fn branch_types(&self)->&[ValType] { if self.kind==Kind::Loop { &self.params } else { &self.results } } }
40	
41	struct Compiler<'a> {
42	    env:&'a Env, r:Reader<'a>, out:String, stack:Vec<Option<ValType>>, frames:Vec<Frame>,
43	    locals:Vec<ValType>, max_stack:usize, max_args:usize, max_results:usize,
44	    next_id:usize, numeric:BTreeSet<u32>,
45	}
46	impl<'a> Compiler<'a> {
47	    fn line(&mut self, line:impl AsRef<str>) { writeln!(self.out,"  {}",line.as_ref()).unwrap(); }
48	    fn fresh(&mut self)->String { let n=self.next_id; self.next_id+=1; format!("%v{n}") }
49	    fn label(&mut self)->String { let n=self.next_id; self.next_id+=1; format!("b{n}") }
50	    fn put_label(&mut self,l:&str) { writeln!(self.out,"{l}:").unwrap(); }
51	    fn top(&self)->&Frame { self.frames.last().expect("frame") }
52	    fn touch(&mut self, i:usize) {self.max_stack=self.max_stack.max(i+1);}
53	    fn pop(&mut self, want:Option<ValType>)->Result<usize,String> {
54	        let f=self.top(); let (base,unreachable)=(f.base,f.unreachable);
55	        if self.stack.len()==base {
56	            if unreachable { self.touch(base); return Ok(base); }
57	            return Err("operand stack underflow".into());
58	        }
59	        let i=self.stack.len()-1; let actual=self.stack.pop().unwrap();
60	        if let (Some(x),Some(y))=(actual,want) { if x!=y { return Err(format!("operand type mismatch: {x:?} vs {y:?}")); } }
61	        Ok(i)
62	    }
63	    fn push(&mut self,t:Option<ValType>)->usize {let i=self.stack.len(); self.stack.push(t); self.touch(i); i}
64	    fn load(&mut self, i:usize)->String {self.touch(i); let v=self.fresh(); self.line(format!("{v} = load i128, ptr %s{i}, align 16")); v}
65	    fn store(&mut self,i:usize,v:&str) {self.touch(i); self.line(format!("store i128 {v}, ptr %s{i}, align 16"));}
66	    fn push_val(&mut self,t:ValType,v:&str) {let i=self.push(Some(t));self.store(i,v);}
67	    fn get_pop(&mut self,t:ValType)->Result<String,String> {let i=self.pop(Some(t))?; Ok(self.load(i))}
68	    fn i32(&mut self,v:&str)->String {let x=self.fresh();self.line(format!("{x} = trunc i128 {v} to i32"));x}
69	    fn widen(&mut self,v:&str,ty:&str)->String {let x=self.fresh();self.line(format!("{x} = zext {ty} {v} to i128"));x}
70	    fn dead(&mut self) {let f=self.frames.last_mut().unwrap(); self.stack.truncate(f.base);f.unreachable=true;let lab=self.label();self.put_label(&lab);}
71	    fn check_args(&mut self, types:&[ValType])->Result<Vec<usize>,String> {
