1	//! Lower scalar WebAssembly numeric instructions to poison-free LLVM helpers.
2	use crate::wasm::ValType::{self, F32, F64, I32, I64};
3	use std::fmt::Write;
4	
5	pub fn signature(op: u32) -> Option<(Vec<ValType>, ValType)> {
6	    let (a, b, r) = match op {
7	        0x45 => (I32, false, I32), 0x46..=0x4f => (I32, true, I32),
8	        0x50 => (I64, false, I32), 0x51..=0x5a => (I64, true, I32),
9	        0x5b..=0x60 => (F32, true, I32), 0x61..=0x66 => (F64, true, I32),
10	        0x67..=0x69 => (I32, false, I32), 0x6a..=0x78 => (I32, true, I32),
11	        0x79..=0x7b => (I64, false, I64), 0x7c..=0x8a => (I64, true, I64),
12	        0x8b..=0x91 => (F32, false, F32), 0x92..=0x98 => (F32, true, F32),
13	        0x99..=0x9f => (F64, false, F64), 0xa0..=0xa6 => (F64, true, F64),
14	        0xa7 => (I64, false, I32),
15	        0xa8..=0xa9 => (F32, false, I32), 0xaa..=0xab => (F64, false, I32),
16	        0xac..=0xad => (I32, false, I64),
17	        0xae..=0xaf => (F32, false, I64), 0xb0..=0xb1 => (F64, false, I64),
18	        0xb2..=0xb3 => (I32, false, F32), 0xb4..=0xb5 => (I64, false, F32),
19	        0xb6 => (F64, false, F32),
20	        0xb7..=0xb8 => (I32, false, F64), 0xb9..=0xba => (I64, false, F64),
21	        0xbb => (F32, false, F64), 0xbc => (F32, false, I32), 0xbd => (F64, false, I64),
22	        0xbe => (I32, false, F32), 0xbf => (I64, false, F64),
23	        0xc0..=0xc1 => (I32, false, I32), 0xc2..=0xc4 => (I64, false, I64),
24	        0x100..=0x101 => (F32, false, I32), 0x102..=0x103 => (F64, false, I32),
25	        0x104..=0x105 => (F32, false, I64), 0x106..=0x107 => (F64, false, I64),
26	        _ => return None,
27	    };
28	    Some((if b { vec![a,a] } else { vec![a] }, r))
29	}
30	
31	fn bits(t: ValType) -> &'static str { match t { I32 | F32 => "i32", I64 | F64 => "i64", _ => unreachable!() } }
32	fn float(t: ValType) -> &'static str { match t { F32 => "float", F64 => "double", _ => unreachable!() } }
33	fn suffix(t: ValType) -> &'static str { match t { I32 => "i32", I64 => "i64", F32 => "f32", F64 => "f64", _ => unreachable!() } }
34	fn is_float(t: ValType) -> bool { matches!(t, F32 | F64) }
35	
36	pub fn declarations() -> String {
37	    let mut s = String::new();
38	    for i in ["i32", "i64"] {
39	        for f in ["ctlz", "cttz"] { writeln!(s, "declare {i} @llvm.{f}.{i}({i}, i1)").unwrap(); }
40	        writeln!(s, "declare {i} @llvm.ctpop.{i}({i})").unwrap();
41	        for f in ["fshl", "fshr"] { writeln!(s, "declare {i} @llvm.{f}.{i}({i}, {i}, {i})").unwrap(); }
42	    }
43	    for (n, t) in [("f32", "float"), ("f64", "double")] {
44	        for f in ["fabs", "ceil", "floor", "trunc", "roundeven", "sqrt"] { writeln!(s, "declare {t} @llvm.{f}.{n}({t})").unwrap(); }
45	        for f in ["minimum", "maximum", "copysign"] { writeln!(s, "declare {t} @llvm.{f}.{n}({t}, {t})").unwrap(); }
46	        for i in ["i32", "i64"] { for f in ["fptosi", "fptoui"] { writeln!(s, "declare {i} @llvm.{f}.sat.{i}.{n}({t})").unwrap(); } }
47	    }
48	    s
49	}
50	
51	/// The input and output are bit patterns in the low bytes of 128-bit slots.
52	pub fn helper(op: u32) -> Result<String, String> {
53	    let (args, result) = signature(op).ok_or_else(|| format!("unknown scalar opcode {op:x}"))?;
54	    let a = args[0];
55	    let bt = bits(a);
56	    let mut s = format!("define internal i128 @w2l_num_{op:x}(i128 %a, i128 %b) {{\nentry:\n");
57	    writeln!(s, "  %ax = trunc i128 %a to {bt}").unwrap();
58	    if is_float(a) { writeln!(s, "  %x = bitcast {bt} %ax to {}", float(a)).unwrap(); }
59	    else { writeln!(s, "  %x = add {bt} %ax, 0").unwrap(); }
60	    if args.len() == 2 {
61	        writeln!(s, "  %by = trunc i128 %b to {bt}").unwrap();
62	        if is_float(a) { writeln!(s, "  %y = bitcast {bt} %by to {}", float(a)).unwrap(); }
63	        else { writeln!(s, "  %y = add {bt} %by, 0").unwrap(); }
64	    }
65	    match op {
66	        0x45 | 0x50 => { writeln!(s, "  %cmp = icmp eq {bt} %x, 0\n  %r = zext i1 %cmp to i32").unwrap(); }
67	        0x46..=0x4f | 0x51..=0x5a => {
68	            let base = if op <= 0x4f { 0x46 } else { 0x51 };
69	            let pred = ["eq", "ne", "slt", "ult", "sgt", "ugt", "sle", "ule", "sge", "uge"][(op-base) as usize];
70	            writeln!(s, "  %cmp = icmp {pred} {bt} %x, %y\n  %r = zext i1 %cmp to i32").unwrap();
71	        }
72	        0x5b..=0x66 => {
73	            let base = if op <= 0x60 { 0x5b } else { 0x61 };
74	            let pred = ["oeq", "une", "olt", "ogt", "ole", "oge"][(op-base) as usize];
75	            writeln!(s, "  %cmp = fcmp {pred} {} %x, %y\n  %r = zext i1 %cmp to i32", float(a)).unwrap();
76	        }
77	        0x67..=0x78 | 0x79..=0x8a => {
78	            let n = op - if op <= 0x78 { 0x67 } else { 0x79 };
79	            match n {
80	                0 | 1 => { let f = if n==0 {"ctlz"} else {"cttz"}; writeln!(s, "  %r = call {bt} @llvm.{f}.{bt}({bt} %x, i1 false)").unwrap(); }
81	                2 => writeln!(s, "  %r = call {bt} @llvm.ctpop.{bt}({bt} %x)").unwrap(),
82	                3..=5 | 10..=12 => { let inst = ["add","sub","mul","","","","","and","or","xor"][(n-3) as usize]; writeln!(s, "  %r = {inst} {bt} %x, %y").unwrap(); }
83	                6..=9 => {
84	                    writeln!(s, "  %zero = icmp eq {bt} %y, 0\n  br i1 %zero, label %trap_zero, label %nonzero\ntrap_zero:\n  call void @w2l_trap(i32 1)\n  unreachable\nnonzero:").unwrap();
85	                    let signed = n==6 || n==8;
86	                    if signed {
87	                        let min = if a == I32 {"-2147483648"} else {"-9223372036854775808"};
88	                        writeln!(s, "  %min = icmp eq {bt} %x, {min}\n  %minusone = icmp eq {bt} %y, -1\n  %overflow = and i1 %min, %minusone").unwrap();
89	                        if n==6 { writeln!(s, "  br i1 %overflow, label %trap_overflow, label %do_div\ntrap_overflow:\n  call void @w2l_trap(i32 2)\n  unreachable\ndo_div:\n  %r = sdiv {bt} %x, %y").unwrap(); }
90	                        else { writeln!(s, "  %safe_y = select i1 %overflow, {bt} 1, {bt} %y\n  %r = srem {bt} %x, %safe_y").unwrap(); }
91	                    } else { let inst = if n==7 {"udiv"} else {"urem"}; writeln!(s, "  %r = {inst} {bt} %x, %y").unwrap(); }
92	                }
93	                13..=15 => { let mask = if a==I32 {31} else {63}; let inst = ["shl","ashr","lshr"][(n-13) as usize]; writeln!(s, "  %count = and {bt} %y, {mask}\n  %r = {inst} {bt} %x, %count").unwrap(); }
94	                16..=17 => { let f = if n==16 {"fshl"} else {"fshr"}; writeln!(s, "  %r = call {bt} @llvm.{f}.{bt}({bt} %x, {bt} %x, {bt} %y)").unwrap(); }
95	                _ => unreachable!(),
96	            }
97	        }
98	        0x8b..=0xa6 => {
99	            let base = if op <= 0x98 { 0x8b } else { 0x99 }; let n = op-base;
100	            let ft=float(a); let suff=suffix(a);
101	            match n {
102	                0 => writeln!(s,"  %r = call {ft} @llvm.fabs.{suff}({ft} %x)").unwrap(),
103	                1 => writeln!(s,"  %r = fneg {ft} %x").unwrap(),
104	                2..=6 => { let f=["ceil","floor","trunc","roundeven","sqrt"][(n-2) as usize]; writeln!(s,"  %r = call {ft} @llvm.{f}.{suff}({ft} %x)").unwrap(); }
105	                7..=10 => { let f=["fadd","fsub","fmul","fdiv"][(n-7) as usize]; writeln!(s,"  %r = {f} {ft} %x, %y").unwrap(); }
106	                11..=13 => { let f=["minimum","maximum","copysign"][(n-11) as usize]; writeln!(s,"  %r = call {ft} @llvm.{f}.{suff}({ft} %x, {ft} %y)").unwrap(); }
107	                _ => unreachable!(),
108	            }
109	        }
110	        0xa7 => writeln!(s,"  %r = trunc i64 %x to i32").unwrap(),
111	        0xac | 0xad => { let f=if op==0xac {"sext"} else {"zext"}; writeln!(s,"  %r = {f} i32 %x to i64").unwrap(); }
112	        0xa8..=0xab | 0xae..=0xb1 | 0x100..=0x107 => {
113	            let signed = match op { 0xa8|0xaa|0xae|0xb0|0x100|0x102|0x104|0x106=>true, _=>false };
114	            let f=if signed {"fptosi"} else {"fptoui"}; let out=bits(result); let ft=float(a); let fs=suffix(a);
115	            if op < 0x100 {
116	                writeln!(s,"  %isnan = fcmp uno {ft} %x, %x\n  br i1 %isnan, label %trap_nan, label %range\ntrap_nan:\n  call void @w2l_trap(i32 3)\n  unreachable\nrange:").unwrap();
117	                // truncation first makes the open lower endpoint (-1 for unsigned,
118	                // MIN-1 for signed) exact even when the source is f64.
119	                if a==F32 { writeln!(s,"  %wide = fpext float %x to double").unwrap(); } else { writeln!(s,"  %wide = fadd double %x, 0.000000e+00").unwrap(); }
120	                writeln!(s,"  %truncated = call double @llvm.trunc.f64(double %wide)").unwrap();
121	                let (lo,hi) = match (result,signed) {
122	                    (I32,true) => ("-2.147483648000000e+09","2.147483648000000e+09"),
123	                    (I32,false) => ("0.000000e+00","4.294967296000000e+09"),
124	                    (I64,true) => ("-9.223372036854775808000000e+18","9.223372036854775808000000e+18"),
125	                    _ => ("0.000000e+00","1.844674407370955161600000e+19"),
126	                };
127	                writeln!(s,"  %low = fcmp olt double %truncated, {lo}\n  %high = fcmp oge double %truncated, {hi}\n  %bad = or i1 %low, %high\n  br i1 %bad, label %trap_range, label %convert\ntrap_range:\n  call void @w2l_trap(i32 2)\n  unreachable\nconvert:").unwrap();
128	            }
129	            writeln!(s,"  %r = call {out} @llvm.{f}.sat.{out}.{fs}({ft} %x)").unwrap();
130	        }
131	        0xb2..=0xb5 | 0xb7..=0xba => {
132	            let signed=matches!(op,0xb2|0xb4|0xb7|0xb9); let f=if signed {"sitofp"} else {"uitofp"};
133	            writeln!(s,"  %r = {f} {bt} %x to {}",float(result)).unwrap();
134	        }
135	        0xb6 => writeln!(s,"  %r = fptrunc double %x to float").unwrap(),
136	        0xbb => writeln!(s,"  %r = fpext float %x to double").unwrap(),
137	        0xbc..=0xbf => { // Reinterpretation is already represented in raw bits.
138	            writeln!(s,"  %r = bitcast {} %x to {}", if is_float(a) {float(a)} else {bits(a)}, if is_float(result) {float(result)} else {bits(result)}).unwrap();
139	        }
140	        0xc0..=0xc4 => {
141	            let narrow = match op {0xc0|0xc2=>"i8", 0xc1|0xc3=>"i16", _=>"i32"};
142	            writeln!(s,"  %narrow = trunc {bt} %x to {narrow}\n  %r = sext {narrow} %narrow to {bt}").unwrap();
143	        }
144	        _ => return Err(format!("unimplemented scalar opcode {op:x}")),
145	    }
146	    let rt=bits(result);
147	    if is_float(result) { writeln!(s,"  %rbits = bitcast {} %r to {rt}",float(result)).unwrap(); }
148	    else { writeln!(s,"  %rbits = add {rt} %r, 0").unwrap(); }
149	    writeln!(s,"  %wide_result = zext {rt} %rbits to i128\n  ret i128 %wide_result\n}}\n").unwrap();
150	    Ok(s)
151	}
